import { ChangeDetectionStrategy, Component, booleanAttribute, input } from '@angular/core';

@Component({
  selector: 'select[aevkoNativeSelect]',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './native-select.directive.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    '[attr.aria-invalid]': 'invalid() ? "true" : null',
    '[attr.data-invalid]': 'invalid() ? "true" : null',
  },
})
export class AevkoNativeSelect {
  readonly invalid = input(false, { transform: booleanAttribute });
}

:host {
  appearance: none;
  background-color: var(--aevko-background, #ffffff);
  background-image:
    linear-gradient(45deg, transparent 50%, currentcolor 50%),
    linear-gradient(135deg, currentcolor 50%, transparent 50%);
  background-position:
    calc(100% - 1rem) 52%,
    calc(100% - 0.7rem) 52%;
  background-repeat: no-repeat;
  background-size:
    0.35rem 0.35rem,
    0.35rem 0.35rem;
  border: 1px solid color-mix(in srgb, var(--aevko-foreground, #20201e) 45%, transparent);
  border-radius: var(--aevko-radius, 0);
  box-sizing: border-box;
  color: var(--aevko-foreground, #20201e);
  font: 500 1rem/1.4 var(--aevko-font-sans, sans-serif);
  min-height: 2.75rem;
  padding: 0.625rem 2.25rem 0.625rem 0.75rem;
  width: 100%;
}
:host:focus-visible {
  border-color: var(--aevko-focus, #a1a1aa);
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
:host([data-invalid='true']) {
  border-color: var(--aevko-danger, #3f3f3f);
}
:host:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
